import{_ as r,o as t,c as n,a3 as a}from"./chunks/framework.-MjGFDw0.js";const v=JSON.parse('{"title":"Het prestatiebestand thuisverpleging","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"nurse/index.md","filePath":"nurse/index.md","lastUpdated":1795770237000}'),i={name:"nurse/index.md"};function o(s,e,d,p,l,g){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="het-prestatiebestand-thuisverpleging" tabindex="-1">Het prestatiebestand thuisverpleging <a class="header-anchor" href="#het-prestatiebestand-thuisverpleging" aria-label="Permalink to &quot;Het prestatiebestand thuisverpleging&quot;">​</a></h1><p>Het prestatiebestand (nurse-xml) is het XML-bestand waarmee een softwarepakket voor thuisverpleging de geregistreerde zorg aan TDM3 bezorgt. De zorgverlener registreert de zorg in het pakket, het pakket exporteert het prestatiebestand, en TDM3 doet de rest van de keten: valideren, opkuisen en aanvullen, factureren, verzenden en afrekenen met ziekenfondsen, verzekeringen, OCMW&#39;s, medische huizen en patiënten, en doorstorten aan de praktijk.</p><div class="tip custom-block"><p class="custom-block-title">Specificatie</p><ul><li><a href="/pr-preview/pr-13/schemas/tdm3prestatiebestand.xsd">XSD-schema downloaden</a></li><li><a href="/pr-preview/pr-13/nurse/nodes">Nodes</a>: alle elementen van het bestand, met type en betekenis</li><li><a href="/pr-preview/pr-13/nurse/faq">Veelgestelde vragen</a>: vragen van softwarehuizen, met het antwoord van TDM3</li><li><a href="/pr-preview/pr-13/nurse/CHANGELOG">Changelog</a>: wijzigingen aan de specificatie</li></ul></div><h2 id="principes" tabindex="-1">Principes <a class="header-anchor" href="#principes" aria-label="Permalink to &quot;Principes&quot;">​</a></h2><ul><li><strong>Per praktijk, per facturatiemaand.</strong> Normaal gezien levert het pakket één bestand per praktijk per facturatiemaand. Meerdere bestanden voor dezelfde praktijk en maand mogen ook: TDM3 voegt ze samen.</li><li><strong>De verenigingscode is verplicht.</strong> Ze identificeert de praktijk en wordt door TDM3 toegekend. Zie <a href="/pr-preview/pr-13/nurse/wie#de-praktijk">Wie</a>.</li><li><strong>Een eigen softwarehuiscode.</strong> Elk softwarepakket krijgt van TDM3 een code voor de node <a href="/pr-preview/pr-13/nurse/nodes#node-softwarehuis">softwarehuis</a>.</li><li><strong>Geen tarificatielogica in het pakket.</strong> Forfaits, basisverstrekkingen en supplementen voegt TDM3 zelf toe. Zie <a href="/pr-preview/pr-13/nurse/wat#wat-tdm3-zelf-toevoegt">Wat TDM3 zelf toevoegt</a>.</li><li><strong>Dicht bij de RIZIV-facturatie-instructies.</strong> De velden volgen de instructies zo nauw mogelijk. Optionele velden dienen voor maatwerk en een rijkere dataset: niet elk pakket hoeft alles aan te leveren.</li></ul><h2 id="opbouw-van-het-bestand" tabindex="-1">Opbouw van het bestand <a class="header-anchor" href="#opbouw-van-het-bestand" aria-label="Permalink to &quot;Opbouw van het bestand&quot;">​</a></h2><p>De kop van het bestand bestaat uit de nodes <a href="/pr-preview/pr-13/nurse/nodes#node-softwarehuis">softwarehuis</a>, <a href="/pr-preview/pr-13/nurse/nodes#node-tarificatiedienst">tarificatiedienst</a> en <a href="/pr-preview/pr-13/nurse/nodes#node-facturatieperiode">facturatieperiode</a>. De rest van het bestand beantwoordt vier vragen.</p><table tabindex="0"><thead><tr><th></th><th>Vraag</th><th>Belangrijkste gegevens</th></tr></thead><tbody><tr><td><strong><a href="/pr-preview/pr-13/nurse/wie">Wie</a></strong></td><td>Wie voert de zorg uit?</td><td><a href="/pr-preview/pr-13/nurse/nodes#node-vereniging">vereniging</a>: de verenigingscode is de praktijk. De zorgverlener: RIZIV-nummers op <a href="/pr-preview/pr-13/nurse/nodes#node-uitgevoerdezorg">uitgevoerdezorg</a>.</td></tr><tr><td><strong><a href="/pr-preview/pr-13/nurse/wat">Wat</a></strong></td><td>Welke zorg, bij welke patiënt?</td><td><a href="/pr-preview/pr-13/nurse/nodes#node-patientgegevens">patientgegevens</a>, <a href="/pr-preview/pr-13/nurse/nodes#node-uitgevoerdezorg">uitgevoerdezorg</a>, <a href="/pr-preview/pr-13/nurse/nodes#node-profielen">profielen</a>, <a href="/pr-preview/pr-13/nurse/nodes#node-lezingidentiteit">lezingidentiteit</a>, <a href="/pr-preview/pr-13/nurse/nodes#node-kennisgevingwondzorg">kennisgevingwondzorg</a>. Zorg zonder RIZIV-nomenclatuur via 426856 (KB90).</td></tr><tr><td><strong><a href="/pr-preview/pr-13/nurse/aan-wie">Aan wie</a></strong></td><td>Wie betaalt?</td><td>Type bestemmeling, derdebetalergegevens, de patiënt als betaler: remgeld en kanaal van de patiëntfactuur.</td></tr><tr><td><strong><a href="/pr-preview/pr-13/nurse/hoe">Hoe</a></strong></td><td>Hoe wordt er gefactureerd en aangeleverd?</td><td>Type facturering 0, 1, 3 of 5: correcties, herindieningen en crediteringen. Aanlevering per praktijk per maand.</td></tr></tbody></table><h2 id="voorbeelden" tabindex="-1">Voorbeelden <a class="header-anchor" href="#voorbeelden" aria-label="Permalink to &quot;Voorbeelden&quot;">​</a></h2><ul><li><a href="/pr-preview/pr-13/nurse/artikel8">Voorbeelden artikel 8</a>: twaalf uitgewerkte situaties (forfaitpatiënt, meerdere bezoeken per dag, zorgkundige, palliatieve patiënt, complexe wondzorg, KB90, correctieforfait, ...).</li><li><a href="/pr-preview/pr-13/nurse/artikel56">Pilootproject artikel 56</a>: bijkomende instructies voor praktijken in het pilootproject nieuwe praktijkfinanciering.</li><li><a href="/pr-preview/pr-13/nurse/nodes#volledig-voorbeeld">Volledig voorbeeld</a> van een prestatiebestand.</li></ul><p><img src="https://www.plantuml.com/plantuml/svg/NP5HRiCW44J_VGha_roXobLe6CZMBY30jkJJPupNITMl6UtpB0E-rsPBMtxd8IO7ausjPinscj020bR4EfweTbIJRvijU2voWMoRffeW_e_jgOIE5o5Q4uh3CLCyO--KAZ68um9faAQOvJgcYfV7SOBZ8VNY-SIvo4_zHi64o3KALvoKod7uW5oIrrpoWXbHmNQMuPOebMqPsL9qV_fw--YVKDjIZZuPHKZ6OSZcTlioLPNFeUw8g-KrrV56whZgYbmZDdwFabUxxSCTqV5VlG00" alt="Structuur van het prestatiebestand"></p>',11)])])}const h=r(i,[["render",o]]);export{v as __pageData,h as default};
